{"path": "src/db.js", "content": "const mongoose = require('mongoose');
const dotenv = require('dotenv');
dotenv.config();

const uri = process.env.DOCUMENTDB_URI;
if (!uri) {
  console.warn('DOCUMENTDB_URI not set — tests may mock mongoose.');
}

// Connection options — conservative defaults for a long-running Express server per documentdb-connection guidance
const options = {
  // reuse connections, keep pool size reasonable for demo
  maxPoolSize: 50,
  minPoolSize: 10,
  connectTimeoutMS: 10000,
  socketTimeoutMS: 30000,
  serverSelectionTimeoutMS: 5000,
  // retryWrites typically false for DocumentDB; leave driver default unless user-supplied in URI
  // Other options may be provided in the URI itself.
};

let connectionPromise = null;

function connect() {
  if (connectionPromise) return connectionPromise;
  if (!uri) return Promise.reject(new Error('DOCUMENTDB_URI not configured'));
  connectionPromise = mongoose.connect(uri, options).then(() => mongoose);
  return connectionPromise;
}

module.exports = { connect, mongoose };
"}

{"path": "src/models/customerProfile.js", "content": "const { Schema } = require('mongoose');

const CustomerProfileSchema = new Schema({
  customerId: { type: String, required: true, unique: true, index: true },
  crm: { type: Schema.Types.Mixed, default: {} },
  ecommerce: { type: Schema.Types.Mixed, default: {} },
  support: { type: Schema.Types.Mixed, default: {} },
  schemaVersion: { type: Number, default: 1 },
  lastUpdated: { type: Date, default: Date.now }
}, { collection: 'customer_profiles', timestamps: true });

// Static helper to upsert from an event while merging attributes into the subdocument using dot-paths
CustomerProfileSchema.statics.upsertFromEvent = async function (event) {
  const { source, customerId, attributes } = event;
  if (!['crm', 'ecommerce', 'support'].includes(source)) {
    throw new Error('unsupported source');
  }
  if (!customerId) throw new Error('customerId required');

  // Flatten attributes into dot notation under the source prefix
  const setOps = {};
  for (const [k, v] of Object.entries(attributes || {})) {
    setOps[`${source}.${k}`] = v;
  }
  setOps.lastUpdated = new Date();

  const res = await this.updateOne({ customerId }, { $set: setOps }, { upsert: true });
  return res;
};

module.exports = CustomerProfileSchema;
"}

{"path": "src/routes/events.js", "content": "const express = require('express');
const router = express.Router();

module.exports = (CustomerProfileModel) => {
  router.post('/', async (req, res) => {
    try {
      const { source, customerId, attributes } = req.body;
      if (!source || !customerId || !attributes) {
        return res.status(400).json({ error: 'source, customerId, and attributes are required' });
      }
      const result = await CustomerProfileModel.upsertFromEvent({ source, customerId, attributes });
      return res.json({ ok: true, result });
    } catch (err) {
      console.error(err);
      return res.status(500).json({ error: err.message });
    }
  });

  return router;
};
"}

{"path": "src/index.js", "content": "const express = require('express');
const { connect, mongoose } = require('./db');
const CustomerProfileSchema = require('./models/customerProfile');

const app = express();
app.use(express.json());

async function start() {
  await connect();
  const CustomerProfile = mongoose.model('CustomerProfile', CustomerProfileSchema);

  // ensure indexes exist (safe on repeated runs)
  await CustomerProfile.syncIndexes();

  const eventsRouter = require('./routes/events')(CustomerProfile);
  app.use('/events', eventsRouter);

  const port = process.env.PORT || 3000;
  app.listen(port, () => console.log(`Customer360 sample listening on ${port}`));
}

if (require.main === module) {
  start().catch(err => {
    console.error('Failed to start:', err.message);
    process.exit(1);
  });
}

module.exports = app;
"}

