    // Upsert ecommerce
    await CustomerProfile.upsertFromEvent({ source: 'ecommerce', customerId: cid, attributes: { loyaltyLevel: ['bronze','silver','gold'][Math.floor(Math.random()*3)], lastPurchaseAt: new Date() } });
